# Fly-in :: blocked_1
# The direct route is walled off; the fleet must take the detour.
# The zone 'ruins' is unusable and the program says so.

nb_drones: 6

start_hub: port 0 0
end_hub: island 5 0

hub: wall 2 0 [zone=blocked color=red]
hub: ruins 2 -4 [zone=blocked]
hub: reefA 1 3 [zone=priority]
hub: reefB 3 3 [zone=priority]
hub: reefC 1 -3
hub: reefD 3 -3

connection: port-wall
connection: wall-island
connection: port-ruins
connection: port-reefA
connection: reefA-reefB
connection: reefB-island
connection: port-reefC
connection: reefC-reefD
connection: reefD-island
